package com.gameexpert.terrain.mc.feature;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.List;
import java.util.zip.GZIPInputStream;

/** Generated authenticated state rows from exact-state-production-closure-v1.json. */
final class Mc263ExactStateProductionClosureData {
    static final int AUTHENTICATED_STATE_COUNT = 1_472;
    static final String RECEIPT_SHA256 =
            "8da716044ae5b5321119b834ad7cb36fc1414f62cb31886a3d27cde34cb4cfe9";
    private static final String GZIP_BASE64 = "";

    private Mc263ExactStateProductionClosureData() {}

    static List<String> states() {
        try {
            byte[] compressed = Base64.getDecoder().decode(GZIP_BASE64);
            byte[] raw;
            try (GZIPInputStream input = new GZIPInputStream(
                    new ByteArrayInputStream(compressed))) {
                raw = input.readAllBytes();
            }
            List<String> states = new String(raw, StandardCharsets.US_ASCII).lines().toList();
            if (states.size() != AUTHENTICATED_STATE_COUNT) {
                throw new ExceptionInInitializerError(
                        "authenticated exact-state row count drift");
            }
            return states;
        } catch (IOException failure) {
            throw new ExceptionInInitializerError(failure);
        }
    }
}
